//! Role: 解析の設定と、モジュール階層・参照・循環の解析結果を定義する。
use std::{collections::BTreeSet, path::PathBuf};

/// Settings shared by every configuration analyzed for one package.
#[derive(Debug, Clone)]
pub struct Settings {
    pub features: BTreeSet<String>,
    /// Explicit assumptions: these attribute macros preserve the source module hierarchy.
    /// References generated by their expansion are outside source-level analysis.
    pub trusted_attributes: BTreeSet<String>,
    pub trusted_derives: BTreeSet<String>,
    /// これらの macro の展開・token は解析しない。生成・内包される参照は source-level 解析の外。
    pub trusted_macros: BTreeSet<String>,
    /// External glob imports (`crate::module`) known to provide no macros, derives or attributes.
    pub trusted_globs: BTreeSet<String>,
    /// Attribute macros that generate a type named after the PascalCase of the fn they mark:
    /// `#[component] fn user_row` declares `UserRow` beside the fn.
    pub generated_type_attributes: BTreeSet<String>,
    /// Positive maximum number of Unicode scalar values in a Role description.
    pub max_role_chars: usize,
}

/// One configuration: the active cfg lines, e.g. `unix` or `target_os="linux"`.
#[derive(Debug, Clone, Default)]
pub struct Configuration {
    pub cfg: BTreeSet<String>,
}

/// The borrowed inputs of one analysis, passed down the crate.
#[derive(Clone, Copy)]
pub(crate) struct Env<'a> {
    pub(crate) settings: &'a Settings,
    pub(crate) cfg: &'a BTreeSet<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ModuleKind {
    File,
    Inline,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Module {
    pub id: String,
    pub file: PathBuf,
    /// Index of the parent in `ModuleGraph::modules`; `None` only for the root.
    pub parent: Option<usize>,
    pub kind: ModuleKind,
    /// The static inner doc Role without its Role: marker, or the diagnostic that explains
    /// why the module has none.
    pub role: Result<String, String>,
}

#[derive(Debug, Clone, PartialEq, Eq, PartialOrd, Ord)]
pub struct Reference {
    pub from: String,
    pub to: String,
}

#[derive(Debug, Clone)]
pub struct ModuleGraph {
    pub modules: Vec<Module>,
    pub edges: Vec<Reference>,
    /// Strongly connected components with at least two modules.
    pub cycles: Vec<Vec<String>>,
    pub diagnostics: Vec<String>,
}
